978	+/**
979	+ * A seeded match seen from outside: ships sail and turn, players collect sealed sources and claim caches, fight duels
980	+ * (reserving their rubbings) that end in a theft or a draw, leave (their rubbings go into a cache where they were)
981	+ * and join, and buy targeted rumors, sometimes repeating a request id. Some scenarios jump several ticks at once.
982	+ */
983	+function randomScript(scenario: Scenario, config: IntelConfig, map: IntelMapShape): IntelReplayTick[] {
984	+  const draw = generator(scenario.seed);
985	+  const chance = (perMille: number) => draw(1000) < perMille;
986	+  const preset = rulesPresets[scenario.preset];
987	+  const width = map.widthTiles * T;
988	+  const height = map.heightTiles * T;
989	+  const players = new Map<string, SimPlayer>();
990	+  let nextPlayer = 0;
991	+  const join = () => {
992	+    players.set(`crew-${nextPlayer++}`, { x: draw(width), y: draw(height), heading: draw(8) });
993	+  };
994	+  for (let index = 0; index < preset.maxPlayers; index++) join();
995	+  const rubbings = new Map<string, IntelRubbing>();
996	+  const deck = presetRubbings(preset);
997	+  deck.forEach((rubbing, index) => {
998	+    const island = Math.floor(index / preset.sourcesPerIsland);
999	+    // Spread each type over the islands: deal by a seeded shuffle of the deck positions.
1000	+    rubbings.set(rubbing.id, { id: rubbing.id, type: rubbing.type, place: { kind: "source", island, ...islandPoint(map, island) } });
1001	+  });
1002	+  // Shuffle which type sits on which island.
1003	+  const ids = [...rubbings.keys()];
1004	+  for (let index = ids.length - 1; index > 0; index--) {
1005	+    const other = draw(index + 1);
1006	+    const a = rubbings.get(ids[index]!)!;
1007	+    const b = rubbings.get(ids[other]!)!;
1008	+    rubbings.set(a.id, { ...a, place: b.place });
1009	+    rubbings.set(b.id, { ...b, place: a.place });
1010	+  }
1011	+  const duels: { a: string; b: string; until: number }[] = [];
1012	+  const inDuel = (id: string) => duels.some((duel) => duel.a === id || duel.b === id);
1013	+  const heldTypes = (id: string) =>
1014	+    [...rubbings.values()].filter((rubbing) => (rubbing.place.kind === "carried" || rubbing.place.kind === "duel") && rubbing.place.playerId === id).map((rubbing) => rubbing.type);
1015	+  const pick = <T>(items: readonly T[]): T | undefined => (items.length === 0 ? undefined : items[draw(items.length)]);
1016	+  const requestIds: string[] = [];
1017	+
1018	+  const script: IntelReplayTick[] = [];
1019	+  let tick = 0;
1020	+  while (tick < scenario.endTick) {
1021	+    const dt = chance(scenario.skipPerMille) ? 2 + draw(39) : 1;
1022	+    tick += dt;
1023	+    for (const player of players.values()) {
1024	+      if (chance(15)) player.heading = draw(8);
1025	+      const [dx, dy] = DIRECTIONS[player.heading]!;
1026	+      player.x = Math.min(Math.max(player.x + dx * 64 * dt, 0), width - 1);
1027	+      player.y = Math.min(Math.max(player.y + dy * 64 * dt, 0), height - 1);
1028	+      if (player.x === 0 || player.y === 0 || player.x === width - 1 || player.y === height - 1) player.heading = draw(8);
1029	+    }
1030	+    const free = [...players.keys()].filter((id) => !inDuel(id));
1031	+    // Collect a sealed source of a missing type; the ship is then at that island.
1032	+    if (chance(8)) {
1033	+      const id = pick(free);
1034	+      if (id !== undefined) {
1035	+        const held = heldTypes(id);
1036	+        const target = pick([...rubbings.values()].filter((rubbing) => rubbing.place.kind === "source" && !held.includes(rubbing.type)));
1037	+        if (target !== undefined && target.place.kind === "source") {
1038	+          const player = players.get(id)!;
1039	+          player.x = target.place.x;
1040	+          player.y = target.place.y;
1041	+          rubbings.set(target.id, { ...target, place: { kind: "carried", playerId: id } });
1042	+        }
1043	+      }
1044	+    }
1045	+    // Claim a cached copy of a missing type.
1046	+    if (chance(10)) {
1047	+      const id = pick(free);
1048	+      if (id !== undefined) {
1049	+        const held = heldTypes(id);
1050	+        const target = pick([...rubbings.values()].filter((rubbing) => rubbing.place.kind === "cache" && !held.includes(rubbing.type)));
1051	+        if (target !== undefined) rubbings.set(target.id, { ...target, place: { kind: "carried", playerId: id } });
1052	+      }
1053	+    }
1054	+    // Duels reserve both inventories and end in a theft or a draw.
1055	+    for (const duel of duels.filter((candidate) => candidate.until <= tick)) {
1056	+      duels.splice(duels.indexOf(duel), 1);
1057	+      for (const rubbing of rubbings.values()) {
1058	+        if (rubbing.place.kind === "duel") rubbings.set(rubbing.id, { ...rubbing, place: { kind: "carried", playerId: rubbing.place.playerId } });
1059	+      }
1060	+      if (chance(850)) {
1061	+        const [winner, loser] = chance(500) ? [duel.a, duel.b] : [duel.b, duel.a];
1062	+        const winnerTypes = heldTypes(winner);
1063	+        const stolen = pick(
1064	+          [...rubbings.values()].filter(
1065	+            (rubbing) => rubbing.place.kind === "carried" && rubbing.place.playerId === loser && !winnerTypes.includes(rubbing.type),
1066	+          ),
1067	+        );
1068	+        if (stolen !== undefined) rubbings.set(stolen.id, { ...stolen, place: { kind: "carried", playerId: winner } });
1069	+      }
1070	+      for (const rubbing of rubbings.values()) {
1071	+        const place = rubbing.place;
1072	+        if (place.kind === "carried" && inDuel(place.playerId)) rubbings.set(rubbing.id, { ...rubbing, place: { kind: "duel", playerId: place.playerId } });
1073	+      }
1074	+    }
1075	+    if (chance(12)) {
1076	+      const a = pick(free);
1077	+      const b = pick(free.filter((id) => id !== a));
1078	+      if (a !== undefined && b !== undefined) {
1079	+        duels.push({ a, b, until: tick + 20 + draw(80) });
1080	+        for (const rubbing of rubbings.values()) {
1081	+          const place = rubbing.place;
1082	+          if (place.kind === "carried" && (place.playerId === a || place.playerId === b)) {
1083	+            rubbings.set(rubbing.id, { ...rubbing, place: { kind: "duel", playerId: place.playerId } });
1084	+          }
1085	+        }
1086	+      }
1087	+    }
1088	+    // Leaving drops everything into a cache where the ship was; someone new may join.
1089	+    if (chance(2) && players.size > 2) {
1090	+      const id = pick(free);
1091	+      if (id !== undefined) {
1092	+        const player = players.get(id)!;
1093	+        for (const rubbing of rubbings.values()) {
1094	+          if (rubbing.place.kind === "carried" && rubbing.place.playerId === id) rubbings.set(rubbing.id, { ...rubbing, place: { kind: "cache", x: player.x, y: player.y } });
