1096	+        players.delete(id);
1097	+      }
1098	+    }
1099	+    if (chance(2) && players.size < preset.maxPlayers) join();
1100	+
1101	+    const requests: TargetedRumorRequest[] = [];
1102	+    if (tick > config.controlStartTick - 20 && chance(15)) {
1103	+      const playerId = pick([...players.keys(), "nobody"])!;
1104	+      const reuse = requestIds.length > 0 && chance(250);
1105	+      const requestId = reuse ? requestIds[draw(requestIds.length)]! : `req-${requestIds.length}`;
1106	+      if (!reuse) requestIds.push(requestId);
1107	+      requests.push({ requestId, playerId, type: config.types[draw(config.types.length)]! });
1108	+    }
1109	+    const view: IntelWorldView = {
1110	+      tick,
1111	+      players: [...players].map(([id, player]) => ({ id, x: player.x, y: player.y })),
1112	+      rubbings: [...rubbings.values()],
1113	+    };
1114	+    script.push(deepFreeze({ view, requests }));
1115	+  }
1116	+  return script;
