1120	+interface Facts {
1121	+  readonly players: ReadonlySet<string>;
1122	+  readonly held: ReadonlyMap<string, readonly RubbingType[]>;
1123	+  readonly sourceIslands: readonly { type: RubbingType; island: number }[];
