1128	+function factsOf(config: IntelConfig, view: IntelWorldView): Facts {
1129	+  const positions = new Map(view.players.map((player) => [player.id, player]));
1130	+  const held = new Map<string, RubbingType[]>(view.players.map((player) => [player.id, []]));
1131	+  const sourceIslands: { type: RubbingType; island: number }[] = [];
1132	+  const cacheSectors: { type: RubbingType; sector: number }[] = [];
1133	+  const carriers: { type: RubbingType; sector: number; holder: string }[] = [];
1134	+  for (const rubbing of view.rubbings) {
1135	+    const place = rubbing.place;
1136	+    if (place.kind === "source") sourceIslands.push({ type: rubbing.type, island: place.island });
1137	+    else if (place.kind === "cache") cacheSectors.push({ type: rubbing.type, sector: sectorOf(config, place) });
1138	+    else {
1139	+      held.get(place.playerId)!.push(rubbing.type);
1140	+      carriers.push({ type: rubbing.type, sector: sectorOf(config, positions.get(place.playerId)!), holder: place.playerId });
1141	+    }
1142	+  }
1143	+  return { players: new Set(positions.keys()), held, sourceIslands, cacheSectors, carriers };
