1146	+/** The keys each message kind may carry: none is an id, and only `final-route` has a position. */
1147	+const BODY_KEYS: Record<IntelMessageKind, readonly string[]> = {
1148	+  rumor: ["entry", "kind", "reason", "target", "tick", "type"],
1149	+  "carrier-sighting": ["kind", "name", "reason", "sector", "seenTick", "tick", "type"],
1150	+  "no-lead": ["kind", "reason", "tick", "type"],
1151	+  "rumor-stale": ["entry", "kind", "tick", "type"],
1152	+  "rumor-resolved": ["entry", "kind", "tick", "type"],
1153	+  "final-sector": ["kind", "name", "sector", "tick"],
1154	+  "final-route": ["kind", "restored", "tick", "x", "y"],
1155	+  "final-route-inactive": ["kind", "tick"],
1156	+  "sector-reveal": ["caches", "kind", "sources", "tick"],
1157	+  "carrier-report": ["carriers", "kind", "seenTick", "tick"],
1158	+};
1159	+const BROADCASTS: ReadonlySet<IntelMessageKind> = new Set(["final-sector", "sector-reveal", "carrier-report"]);
1160	+const NESTED_KEYS = new Set(["kind", "island", "sector", "name", "type"]);
1161	+
1162	+/** Every kind, outcome and path the property runs must reach, filled as they run. */
1163	+const EXERCISED = new Set<string>();
1164	+const MUST_EXERCISE = [
1165	+  ...Object.keys(BODY_KEYS).map((kind) => `message:${kind}`),
1166	+  ...(["rumor", "sighting", "capped", "none", "duplicate"] satisfies TargetedRumorResult[]).map((result) => `outcome:${result}`),
1167	+  ...["start", "fresh", "targeted", "replacement"].map((reason) => `rumor:${reason}`),
1168	+  ...["fresh", "targeted", "replacement"].map((reason) => `sighting:${reason}`),
1169	+  "rumor:island",
1170	+  "rumor:sector",
1171	+  "route:restored",
1172	+  "sighting:deferred",
1173	+  "skipped-ticks",
1174	+];
