1176	+function allStrings(value: unknown, out: string[] = []): string[] {
1177	+  if (typeof value === "string") out.push(value);
1178	+  else if (Array.isArray(value)) for (const item of value) allStrings(item, out);
1179	+  else if (typeof value === "object" && value !== null) for (const item of Object.values(value)) allStrings(item, out);
1180	+  return out;
