1183	+/**
1184	+ * Checks every message of a run against the design's rules (§3, §5, §11, §16), with the views that produced them. It
1185	+ * returns nothing and throws on the first violation, with the tick and message.
1186	+ */
1187	+class Checker {
1188	+  private readonly rumors = new Map<string, { type: RubbingType; closed: boolean; target: unknown }>();
1189	+  private readonly sightings = new Map<string, number>();
1190	+  private readonly carriersAt = new Map<number, Facts["carriers"]>();
1191	+  private readonly ids = new Set<string>();
1192	+  private previousTick = -Infinity;
1193	+
1194	+  constructor(
1195	+    private readonly config: IntelConfig,
1196	+    private readonly skipping: boolean,
1197	+  ) {}
1198	+
1199	+  check(view: IntelWorldView, messages: readonly IntelMessage[], state: IntelState): void {
1200	+    const config = this.config;
1201	+    const tick = view.tick;
1202	+    if (tick - this.previousTick > 1 && this.previousTick >= config.controlStartTick) EXERCISED.add("skipped-ticks");
1203	+    this.previousTick = tick;
1204	+    const facts = factsOf(config, view);
1205	+    this.carriersAt.set(tick, facts.carriers);
1206	+    for (const player of view.players) this.ids.add(player.id);
1207	+    for (const rubbing of view.rubbings) this.ids.add(rubbing.id);
1208	+    if (state.players.some((player) => player.pending.length > 0)) EXERCISED.add("sighting:deferred");
1209	+    const fail = (message: IntelMessage, why: string): never => {
1210	+      throw new Error(`tick ${tick}: ${why}: ${JSON.stringify(message)}`);
1211	+    };
1212	+    if (tick < config.controlStartTick && messages.length > 0) fail(messages[0]!, "a message before control start");
1213	+    for (const message of messages) {
1214	+      const body = message.body;
1215	+      EXERCISED.add(`message:${body.kind}`);
1216	+      if (body.tick !== tick) fail(message, "wrong tick");
1217	+      // Keys: exactly the allowed ones, nested ones from the small sector/target vocabulary.
1218	+      expect(Object.keys(body).sort()).toEqual([...BODY_KEYS[body.kind]]);
1219	+      for (const nested of ["target", "sources", "caches", "carriers"] as const) {
1220	+        const value = (body as Record<string, unknown>)[nested];
1221	+        if (value === undefined) continue;
1222	+        for (const item of Array.isArray(value) ? value : [value]) {
1223	+          for (const key of Object.keys(item as object)) if (!NESTED_KEYS.has(key)) fail(message, `nested key ${key}`);
1224	+        }
1225	+      }
1226	+      // No id anywhere in a body.
1227	+      for (const text of allStrings(body)) if (this.ids.has(text)) fail(message, `the id ${text} leaks`);
1228	+      // Addressing: broadcasts to everyone, everything else to one player present now.
1229	+      if (BROADCASTS.has(body.kind)) {
1230	+        if (message.to.kind !== "everyone") fail(message, "a broadcast addressed to someone");
1231	+        continue;
1232	+      }
1233	+      if (message.to.kind !== "player" || !facts.players.has(message.to.playerId)) fail(message, "not addressed to one present player");
1234	+      const recipient = (message.to as { playerId: string }).playerId;
1235	+      const held = facts.held.get(recipient)!;
1236	+      const complete = config.types.every((type) => held.includes(type));
1237	+      const key = (entry: number) => `${recipient}#${entry}`;
1238	+      switch (body.kind) {
1239	+        case "final-route":
1240	+          // The only exact position ever sent, and only to a full-set holder.
1241	+          if (!complete || body.x !== config.finalIsland.x || body.y !== config.finalIsland.y) fail(message, "a route to a player without a full set");
1242	+          if (body.restored) EXERCISED.add("route:restored");
1243	+          break;
1244	+        case "final-route-inactive":
1245	+          if (complete) fail(message, "a route suspended for a full set");
1246	+          break;
1247	+        case "rumor": {
1248	+          EXERCISED.add(`rumor:${body.reason}`);
1249	+          EXERCISED.add(`rumor:${body.target.kind}`);
1250	+          if (held.includes(body.type)) fail(message, "a rumor for a held type");
1251	+          const target = body.target;
1252	+          const there =
1253	+            target.kind === "island"
1254	+              ? facts.sourceIslands.some((source) => source.type === body.type && source.island === target.island)
1255	+              : facts.cacheSectors.some((cache) => cache.type === body.type && cache.sector === target.sector);
1256	+          if (!there) fail(message, "a rumor pointing at nothing");
