1259	+          break;
1260	+        }
1261	+        case "rumor-stale":
1262	+        case "rumor-resolved": {
1263	+          // Only journal rumors close; a carrier sighting has no entry, so it can never go stale.
1264	+          const rumor = this.rumors.get(key(body.entry));
1265	+          if (rumor === undefined || rumor.closed || rumor.type !== body.type) fail(message, "closing no open journal rumor");
1266	+          rumor!.closed = true;
1267	+          if (body.kind === "rumor-resolved" && !held.includes(body.type)) fail(message, "resolved without the type");
1268	+          if (body.kind === "rumor-stale") {
1269	+            if (held.includes(body.type)) fail(message, "stale although the holder has the type");
1270	+            const target = rumor!.target as { kind: "island"; island: number } | { kind: "sector"; sector: number };
1271	+            const there =
1272	+              target.kind === "island"
1273	+                ? facts.sourceIslands.some((source) => source.type === body.type && source.island === target.island)
1274	+                : facts.cacheSectors.some((cache) => cache.type === body.type && cache.sector === target.sector);
1275	+            if (there) fail(message, "stale while the target still holds the type");
1276	+          }
1277	+          break;
1278	+        }
1279	+        case "carrier-sighting": {
1280	+          EXERCISED.add(`sighting:${body.reason}`);
1281	+          if (held.includes(body.type)) fail(message, "a sighting for a held type");
1282	+          if (body.seenTick >= tick) fail(message, "a sighting of the present");
1283	+          const age = tick - body.seenTick;
1284	+          const interval = config.carrierIntervalTicks;
1285	+          if (!this.skipping && (age < interval || age >= 2 * interval)) fail(message, `a sighting ${age} ticks old`);
1286	+          const then = this.carriersAt.get(body.seenTick);
1287	+          if (then === undefined) fail(message, "a sighting of a tick never seen");
1288	+          if (!then!.some((carrier) => carrier.type === body.type && carrier.sector === body.sector && carrier.holder !== recipient)) {
