1293	+            const count = (this.sightings.get(snapshot) ?? 0) + 1;
1294	+            if (count > 1) fail(message, "a second sighting in one snapshot");
1295	+            this.sightings.set(snapshot, count);
1296	+          }
1297	+          break;
1298	+        }
1299	+        case "no-lead":
1300	+          if (held.includes(body.type)) fail(message, "a no-lead for a held type");
1301	+          break;
1302	+      }
1303	+    }
1304	+  }
