1311	+    finalIsland: { x: (map.widthTiles * T) >> 1, y: ((map.heightTiles * T) >> 1) + 77 },
1312	+    controlStartTick: START,
1313	+    map,
1314	+    ...(scenario.realTimes ? {} : { rules: QUICK_RULES }),
