1319	+describe("intel property runs (§3, §5, §11, §16)", () => {
1320	+  for (const scenario of SCENARIOS) {
1321	+    it(`keep every message within the rules: ${scenario.name}`, { timeout: 120_000 }, () => {
1322	+      const { config, script } = setup(scenario);
1323	+      if (scenario.realTimes && scenario.skipPerMille === 0) {
1324	+        expect(config.carrierIntervalTicks).toBe(600);
1325	+        expect(script.at(-1)!.view.tick - config.controlStartTick).toBeGreaterThanOrEqual(36_000);
1326	+        expect(script.at(-1)!.view.tick).toBeGreaterThan(config.carrierRevealTick + 4 * config.carrierIntervalTicks);
1327	+      }
1328	+      const checker = new Checker(config, scenario.skipPerMille > 0);
1329	+      let state = createIntelState(config, scenario.seed);
1330	+      const kinds = new Set<string>();
1331	+      const messages: IntelMessage[] = [];
1332	+      for (const { view, requests } of script) {
1333	+        // Frozen (views are frozen too), so a step that wrote into its input would throw.
1334	+        const stepped = stepIntel(config, deepFreeze(state), view, requests ?? []);
1335	+        messages.push(...stepped.messages);
1336	+        expect(stepped.outcomes.map((outcome) => outcome.requestId)).toEqual((requests ?? []).map((request) => request.requestId));
1337	+        for (const outcome of stepped.outcomes) EXERCISED.add(`outcome:${outcome.result}`);
1338	+        checker.check(view, stepped.messages, stepped.state);
1339	+        for (const message of stepped.messages) kinds.add(message.body.kind);
1340	+        state = stepped.state;
1341	+      }
1342	+      // The run reached the reveals it spans.
1343	+      expect(kinds.has("sector-reveal") && kinds.has("carrier-report")).toBe(true);
1344	+      // Replaying the same script from the same seed reaches the same state.
1345	+      const replayed = replayIntel(config, createIntelState(config, scenario.seed), script);
1346	+      expect(replayed.hash).toBe(hashState(state));
